-- SELECT only; function body checks plus effective client ACLs.
select (select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_installment_signature_guard()'))='f58ed4dcd15059b321f8c7fd3531375b' as body_0,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_installment_collection_guard()'))='f9006eecee5cc6943661c080e46aa0f5' as body_1,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_installment_request_v2(text,jsonb)'))='f483f6a2b8b0ba52f6255c4c718163dd' as body_2,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_member_sign_installment(text,integer,text)'))='372f889a5647658f2b6a32a454cfe971' as body_3,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_member_sign_installment_v2(text,text,text)'))='c6b26028608a87f2dbf9c7118a025a84' as body_4,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_installment_terms(text,integer,numeric,text,integer)'))='bb7a75d11c0ce0634af87e03eda10e00' as body_5,
(select md5(prosrc) from pg_proc where oid=to_regprocedure('fn_installment_collect_v2(text,text,jsonb,boolean,jsonb)'))='eb223c042b68f429a036040da4b9ba05' as body_6,
(has_function_privilege('authenticated','fn_installment_request_v2(text,jsonb)','execute') and not has_function_privilege('anon','fn_installment_request_v2(text,jsonb)','execute')) as api_0,(has_function_privilege('authenticated','fn_member_sign_installment_v2(text,text,text)','execute') and not has_function_privilege('anon','fn_member_sign_installment_v2(text,text,text)','execute')) as api_1,(has_function_privilege('authenticated','fn_installment_collect_v2(text,text,jsonb,boolean,jsonb)','execute') and not has_function_privilege('anon','fn_installment_collect_v2(text,text,jsonb,boolean,jsonb)','execute')) as api_2,(has_function_privilege('authenticated','fn_member_sign_installment(text,integer,text)','execute') and not has_function_privilege('anon','fn_member_sign_installment(text,integer,text)','execute')) as api_3,
(select relrowsecurity from pg_class where oid=to_regclass('public.installment_receipts')) as private_receipts_rls,
not exists(select 1 from pg_policies where schemaname='public' and tablename='installment_receipts') as no_receipt_policies,
not exists(select 1 from unnest(array['anon','authenticated','service_role']) role where has_table_privilege(role,'public.installment_receipts','select,insert,update,delete,truncate,references,trigger')) as no_receipt_table_grants,
(not has_function_privilege('authenticated','fn_installment_signature_guard()','execute') and not has_function_privilege('anon','fn_installment_signature_guard()','execute')) as private_function_0,(not has_function_privilege('authenticated','fn_installment_collection_guard()','execute') and not has_function_privilege('anon','fn_installment_collection_guard()','execute')) as private_function_1,(not has_function_privilege('authenticated','fn_installment_terms(text,integer,numeric,text,integer)','execute') and not has_function_privilege('anon','fn_installment_terms(text,integer,numeric,text,integer)','execute')) as private_function_2,
(select count(*)=2 from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.relnamespace='public'::regnamespace and t.tgenabled='O' and ((c.relname='contracts' and t.tgname='trg_installment_signature_guard' and t.tgfoid='fn_installment_signature_guard()'::regprocedure) or (c.relname='member_tickets' and t.tgname='trg_installment_collection_guard' and t.tgfoid='fn_installment_collection_guard()'::regprocedure))) as guards_enabled;
